// Extract message data from WhatsApp Cloud API webhook payload
const body = $input.first().json.body;

if (!body?.entry?.length) {
  // Could be a webhook test ping from Meta
  return [{ json: { _skip: true, reason: 'Empty or invalid payload â€” possible Meta test ping' } }];
}

const value   = body.entry[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];
const contact = value?.contacts?.[0];

if (!message) {
  // Status update (read receipts, delivery confirmations) â€” not an error
  return [{ json: { _skip: true, reason: 'Status update, no message to process' } }];
}

const messageType = message.type; // text | audio | image | document | sticker | video

return [{
  json: {
    senderPhone:   message.from,
    messageId:     message.id,
    messageType,
    timestamp:     new Date(parseInt(message.timestamp, 10) * 1000).toISOString(),
    textContent:   message.text?.body     ?? null,
    mediaId:       message.audio?.id ?? message.image?.id ?? message.document?.id ?? null,
    mediaMimeType: message.audio?.mime_type ?? message.image?.mime_type ?? null,
    senderName:    contact?.profile?.name ?? null,
    waPhoneId:     value?.metadata?.phone_number_id ?? null,
    rawPayload:    JSON.stringify(body),
    _skip:         false,
  }
}];

if ($json._skip) return [$input.first()];

const fetch = async (url, opts = {}) => {
  const { method = 'GET', headers = {}, body } = opts;
  const resp = await this.helpers.httpRequest({ method, url, headers,
    body: body ? JSON.parse(body) : undefined });
  return { ok: true, json: () => Promise.resolve(resp) };
};

const { senderPhone, senderName, _skip } = $input.first().json;

// Pass-through for status updates and pings
if (_skip) return [$input.first()];

const BASE  = $env.SUPABASE_URL;
const KEY   = $env.SUPABASE_SERVICE_KEY;
const hdrs  = {
  'apikey':        KEY,
  'Authorization': `Bearer ${KEY}`,
  'Content-Type':  'application/json',
};

// â”€â”€ 1. Lookup existing user â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const lookupRes = await fetch(
  `${BASE}/rest/v1/users?whatsapp_phone=eq.${encodeURIComponent(senderPhone)}&select=id,whatsapp_phone,display_name,sheet_id,sheet_url`,
  { headers: hdrs }
);
const existing = await lookupRes.json();

let user;
let isNew = false;

if (existing?.length > 0) {
  user = existing[0];
} else {
  // â”€â”€ 2. Create new user â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const createRes = await fetch(`${BASE}/rest/v1/users`, {
    method:  'POST',
    headers: { ...hdrs, 'Prefer': 'return=representation' },
    body:    JSON.stringify({
      whatsapp_phone: senderPhone,
      display_name:   senderName ?? senderPhone,
    }),
  });
  const created = await createRes.json();
  user  = created[0];
  isNew = true;
  // TODO (Builder 3): call createUserSheet() here when sheet helper API is live
  // then PATCH user.sheet_id + user.sheet_url back to Supabase
}

// â”€â”€ 3. Update last_active_at (non-critical, swallow errors) â”€â”€
try {
  await fetch(`${BASE}/rest/v1/users?id=eq.${user.id}`, {
    method:  'PATCH',
    headers: hdrs,
    body:    JSON.stringify({ last_active_at: new Date().toISOString() }),
  });
} catch (_) { /* intentionally ignored */ }

return [{ json: { ...($input.first().json), user: { ...user, isNew } } }];

// Log incoming WhatsApp message to Supabase REST API.
// Uses fetch (no credential needed) â€” consistent with all other helpers.
// Fails silently: logging must never block message processing.
const fetch = async (url, opts = {}) => {
  const { method = 'GET', headers = {}, body } = opts;
  const resp = await this.helpers.httpRequest({ method, url, headers,
    body: body ? JSON.parse(body) : undefined });
  return { ok: true, json: () => Promise.resolve(resp) };
};

const SB_URL = $env.SUPABASE_URL ?? '';
const SB_KEY = $env.SUPABASE_SERVICE_KEY ?? '';
const item   = $input.first().json;

if (SB_URL && SB_KEY) {
  try {
    await fetch(`${SB_URL}/rest/v1/incoming_messages`, {
      method: 'POST',
      headers: {
        'apikey':         SB_KEY,
        'Authorization':  `Bearer ${SB_KEY}`,
        'Content-Type':   'application/json',
        'Prefer':         'return=minimal',
      },
      body: JSON.stringify({
        user_id:             item.user?.id ?? null,
        whatsapp_message_id: item.messageId,
        phone_from:          item.phone,
        message_type:        item.messageType,
        raw_text:            (item.text ?? '').slice(0, 2000) || null,
        payload:             item.rawPayload,
        status:              'received',
        processed:           false,
      }),
    });
  } catch (err) {
    console.error('[Log Incoming] Failed:', err.message);
  }
}

return $input.all();

// Prepare text message for Claude extraction
// Builder 1: add normalization logic here (lowercase, strip emoji, etc.) if needed

const { textContent, senderPhone, _skip } = $input.first().json;

if (_skip || !textContent?.trim()) {
  return [{ json: { ...($input.first().json), _skipExtraction: true, promptInput: null } }];
}

return [{
  json: {
    ...($input.first().json),
    promptInput:    textContent.trim(),
    processingMode: 'text',
    _skipExtraction: false,
  }
}];

const { senderPhone, messageType } = $input.first().json;

return [{
  json: {
    ...($input.first().json),
    to:        senderPhone,
    replyText: `Maaf kak, saya belum bisa baca pesan ${messageType ?? 'jenis ini'} ðŸ™\n\nSilakan kirim:\nðŸ“ Pesan teks (contoh: "jual 350rb")\nðŸŽ¤ Pesan suara\nðŸ“· Foto struk/nota`,
  }
}];

