const data = $input.first().json;
const originalCtx = $('Handle Text').item.json;

if (data._skipExtraction) {
  return [{ json: { ...originalCtx, _valid: false, _reason: 'Extraction skipped' } }];
}

let extracted = null;
try {
  const claudeText = data.content?.[0]?.text ?? data.text ?? null;
  if (claudeText) {
    const cleaned = claudeText.trim().replace(/^```json\s*/,'').replace(/\s*```$/,'');
    extracted = JSON.parse(cleaned);
  }
} catch (err) {
  return [{ json: { ...originalCtx, _valid: false, _reason: `JSON parse error: ${err.message}`, _rawClaude: data.content?.[0]?.text } }];
}

if (!extracted) {
  return [{ json: { ...originalCtx, _valid: false, _reason: 'No extraction from Claude' } }];
}

const required = ['category', 'nominal'];
const missing  = required.filter(k => extracted[k] == null);
if (missing.length > 0) {
  return [{ json: { ...originalCtx, _valid: false, _reason: `Missing fields: ${missing.join(', ')}`, extractedData: extracted } }];
}

const validCategories = ['pemasukan','pengeluaran','hutang','piutang','bayar_hutang','terima_piutang','unclear'];
if (!validCategories.includes(extracted.category)) {
  extracted.category = 'unclear';
}

return [{ json: { ...originalCtx, extractedData: extracted, _valid: true } }];

const supabaseData = $input.first().json;
const data = $('Validate JSON').item.json;
const ext  = data.extractedData;

if (!ext || !data._valid) {
  return [{ json: { ...supabaseData, ...data, replyText: `Maaf kak, saya kurang paham maksudnya ðŸ™\nBisa dijelaskan lebih detail?\nContoh: "jual 350rb" atau "beli gula 25rb"` } }];
}

const nominal = Number(ext.nominal ?? 0).toLocaleString('id-ID');

const messages = {
  pemasukan:      `âœ… Dicatat! Pemasukan Rp ${nominal}${ext.item ? ` (${ext.item})` : ''} sudah masuk ke buku ya kak ðŸ“’`,
  pengeluaran:    `âœ… Dicatat! Pengeluaran Rp ${nominal}${ext.item ? ` untuk ${ext.item}` : ''} sudah masuk ke buku ðŸ“’`,
  hutang:         `âœ… Dicatat! Hutang Rp ${nominal}${ext.pihak ? ` ke ${ext.pihak}` : ''}${ext.jatuh_tempo ? ` (jatuh tempo: ${ext.jatuh_tempo})` : ''} sudah masuk ðŸ“’`,
  piutang:        `âœ… Dicatat! Piutang Rp ${nominal}${ext.pihak ? ` dari ${ext.pihak}` : ''}${ext.jatuh_tempo ? ` (jatuh tempo: ${ext.jatuh_tempo})` : ''} sudah masuk ðŸ“’`,
  bayar_hutang:   `âœ… Dicatat! Bayar hutang Rp ${nominal}${ext.pihak ? ` ke ${ext.pihak}` : ''} sudah masuk ðŸ“’`,
  terima_piutang: `âœ… Dicatat! Terima piutang Rp ${nominal}${ext.pihak ? ` dari ${ext.pihak}` : ''} sudah masuk ðŸ“’`,
  unclear:        `ðŸ¤” Hmm, saya kurang yakin nih kak. Ini pemasukan atau pengeluaran?\nNominalnya Rp ${nominal}${ext.pihak ? ` (${ext.pihak})` : ''}.`,
};

const replyText = messages[ext.category] ?? messages.unclear;

return [{ json: { ...supabaseData, ...data, replyText, to: data.senderPhone } }];

